corrected_code:
const { S3Client, GetObjectCommand } = require('@aws-sdk/client-s3');
const { getSignedUrl } = require('@aws-sdk/s3-request-presigner');
const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, GetCommand } = require('@aws-sdk/lib-dynamodb');
const s3 = new S3Client({ region: 'us-east-1' });
const ddb = DynamoDBDocumentClient.from(new DynamoDBClient({ region: 'us-east-1' }));

exports.handler = async (event) => {
  const documentId = event.pathParameters.documentId;
  const callerSub = event.requestContext.authorizer.claims.sub;
  const docMeta = await ddb.send(new GetCommand({
    TableName: process.env.TAX_METADATA_TABLE,
    Key: { documentId }
  }));
  if (!docMeta.Item || docMeta.Item.taxpayerId !== callerSub) {
    return { statusCode: 403, body: JSON.stringify({ error: 'Access denied to target tax filing' }) };
  }
  const command = new GetObjectCommand({
    Bucket: process.env.TAX_DOCUMENTS_BUCKET,
    Key: `filings/${documentId}.pdf`
  });
  const presignedUrl = await getSignedUrl(s3, command, { expiresIn: 900 });
  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ downloadUrl: presignedUrl })
  };
};
